      const table=(list,lastColumn)=>`<div class="schedule-table-wrap"><table class="schedule-table"><thead><tr><th>#</th><th>${translate("Task")}</th><th>${translate("Related to")}</th><th>${translate("Due date")}</th><th>${translate(lastColumn)}</th></tr></thead><tbody>${list.map((task,index)=>`<tr${task.done?' class="done-row"':""}><td>${index+1}</td><td>${escape(task.title)}</td><td>${escape(task.contact||translate("No contact"))}</td><td>${escape(date(task.due))}</td>${task.done?`<td class="done-cell">✓ ${translate("Done")}</td>`:`<td class="${task.due<ago(0)?"overdue":""}">${escape(relative(task.due))}</td>`}</tr>`).join("")}</tbody></table></div>`;
