    /** Parse a typed due date: today, tomorrow, "in N days", YYYY-MM-DD, or DD/MM/YYYY. */
    function chatDate(text){const value=plain(text);if(isOneOf(value,["today","اليوم"]))return ago(0);if(isOneOf(value,["tomorrow","بكره","بكرا","غدا","الغد"]))return ago(-1);if(isOneOf(value,["day after tomorrow","بعد بكره","بعد غد"]))return ago(-2);let match=value.match(/^(?:in|بعد)\s*(\d{1,3})\s*(?:days?|يوم|ايام)$/);if(match)return ago(-Number(match[1]));let parts=null;match=value.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);if(match)parts=[match[1],match[2],match[3]];else{match=value.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);if(match)parts=[match[3],match[2],match[1]]}if(!parts)return null;const [year,month,day]=parts.map(Number),iso=`${year}-${String(month).padStart(2,"0")}-${String(day).padStart(2,"0")}`,parsed=new Date(`${iso}T12:00:00`);return parsed.getMonth()+1===month&&parsed.getDate()===day?iso:null}
