    async function sendChat(message){chatBusy=true;$("#chat-send").disabled=true;$("#chat-log").querySelectorAll(".chat-chips").forEach(row=>row.remove());addChatMessage("chat-user",message);try{if(chatState&&isOneOf(message,CHAT_CANCEL)){chatState=null;chatReply(say("Cancelled. What would you like to do?","تم الإلغاء. ماذا تريد أن تفعل؟"),chatMenu())}else if(chatState)await chatAnswer(message);else{const intent=chatIntent(message);if(intent==="summary")chatReply(chatSummary(),chatMenu());else if(intent){chatState={flow:intent,step:0,data:{}};await chatNextStep()}else chatReply(say("I can help with these tasks. Choose one, or type it in your own words.","أستطيع مساعدتك في هذه المهام. اختر واحدة أو اكتبها بكلماتك."),chatMenu())}}catch(error){console.error(error);chatState=null;chatReply(`${say("That didn't work:","لم تنجح العملية:")} ${error.message||say("Could not save changes","تعذر حفظ التغييرات")}`,chatMenu())}finally{chatBusy=false;$("#chat-send").disabled=false;$("#chat-input").focus()}}
    $("#chat-form").addEventListener("submit",event=>{event.preventDefault();const message=$("#chat-input").value.trim();if(!message||chatBusy)return;$("#chat-input").value="";resizeChatInput();sendChat(message)});
