    /** Turn a text input into a contact picker: it lists contacts matching what is typed, and still accepts any name. */
    function setupContactPicker(input){const list=input.nextElementSibling;let active=-1;
      const matches=()=>{const query=plain(input.value);return[...contacts].filter(contact=>!query||plain(`${name(contact)} ${contact.company} ${contact.email}`).includes(query)).sort((a,b)=>name(a).localeCompare(name(b),language)).slice(0,8)};
      const close=()=>{list.hidden=true;input.setAttribute("aria-expanded","false");active=-1};
      const open=()=>{const found=matches();active=-1;list.replaceChildren(...found.map(contact=>{const item=document.createElement("li");item.setAttribute("role","option");item.dataset.value=name(contact);item.innerHTML=`<strong>${escape(name(contact))}</strong>${contact.company?`<span>${escape(contact.company)}</span>`:""}`;return item}));if(!found.length){const empty=document.createElement("li");empty.className="combo-empty";empty.textContent=translate(input.value.trim()?"No matching contact. The name you typed will be saved.":"No contacts yet");list.append(empty)}list.hidden=false;input.setAttribute("aria-expanded","true")};
      const choose=item=>{input.value=item.dataset.value;close()};
      const highlight=step=>{const items=[...list.querySelectorAll("[data-value]")];if(!items.length)return;active=(active+step+items.length)%items.length;items.forEach((item,index)=>item.classList.toggle("active",index===active));items[active].scrollIntoView({block:"nearest"})};
      input.addEventListener("focus",open);input.addEventListener("input",open);input.addEventListener("blur",close);
      input.addEventListener("keydown",event=>{if(event.key==="ArrowDown"||event.key==="ArrowUp"){event.preventDefault();if(list.hidden)open();highlight(event.key==="ArrowDown"?1:-1)}else if(event.key==="Enter"&&!list.hidden&&active>=0){event.preventDefault();choose(list.querySelectorAll("[data-value]")[active])}else if(event.key==="Escape"&&!list.hidden){event.preventDefault();close()}});
      // mousedown keeps focus in the input so the choice lands before blur closes the list.
      list.addEventListener("mousedown",event=>{event.preventDefault();const item=event.target.closest("[data-value]");if(item)choose(item)})}
    // Withaq AI: a floating chat that sends questions to the language model behind /api/chat.
    Object.assign(arabic,{"Withaq AI":"مساعد وثاق","Open Withaq AI":"فتح مساعد وثاق","Answers can take up to a minute.":"قد يستغرق الرد حتى دقيقة.","Ask me anything about sales, customers, or writing a message.":"اسألني عن المبيعات أو العملاء أو صياغة رسالة.","Ask Withaq AI...":"اسأل مساعد وثاق...","Ask Withaq AI":"اسأل مساعد وثاق"});
    let aiBusy=false;
    /** Show the Withaq AI button only when the server reports that chat can answer. */
    async function checkAiAvailability(){try{$("#ai-fab").hidden=!(await api("/chat/status")).available}catch{$("#ai-fab").hidden=true}if($("#ai-fab").hidden)toggleAiPanel(false)}
    /** Open or close the Withaq AI panel from the floating button. */
    function toggleAiPanel(open){$("#ai-panel").hidden=!open;$("#ai-fab").setAttribute("aria-expanded",String(open));if(open)$("#ai-input").focus()}
    /** Append one Withaq AI bubble and keep the newest message in view. */
    function addAiMessage(className,text){const node=document.createElement("div");node.className=`ai-message ${className}`;node.textContent=text;$("#ai-log").append(node);$("#ai-panel").classList.add("has-messages");$("#ai-log").scrollTop=$("#ai-log").scrollHeight;return node}
    /** Grow the question box with its text, up to the CSS max height. */
    function resizeAiInput(){const input=$("#ai-input");input.style.height="auto";input.style.height=`${input.scrollHeight}px`}
    /** Send the question to the model and write its reply into the waiting bubble as it streams in. */
    async function sendAi(message){aiBusy=true;$("#ai-send").disabled=true;addAiMessage("ai-user",message);const pending=addAiMessage("ai-assistant ai-pending",say("Thinking…","جارٍ التفكير…"));try{const response=await fetch(`${API_BASE}/chat/stream`,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${authToken}`},body:JSON.stringify({message})});if(response.status===401){authToken=null;sessionStorage.removeItem("fieldnote-session");showAuth("login");return}if(!response.ok){const result=await response.json().catch(()=>null),error=new Error(readableApiError(result?.detail));error.status=response.status;throw error}const reader=response.body.pipeThrough(new TextDecoderStream()).getReader();let reply="";for(;;){const{done,value}=await reader.read();if(done)break;reply+=value;pending.classList.remove("ai-pending");pending.textContent=reply.trimStart();$("#ai-log").scrollTop=$("#ai-log").scrollHeight}if(!reply.trim())throw new Error(say("No answer came back.","لم يصل أي رد."))}catch(error){console.error(error);pending.classList.add("ai-error");pending.textContent=error.status===503?say("The AI assistant isn't available right now.","المساعد الذكي غير متاح حاليًا."):`${say("That didn't work:","لم تنجح العملية:")} ${error.message}`}finally{pending.classList.remove("ai-pending");aiBusy=false;$("#ai-send").disabled=false;$("#ai-log").scrollTop=$("#ai-log").scrollHeight;$("#ai-input").focus()}}
    $("#ai-fab").addEventListener("click",()=>toggleAiPanel($("#ai-panel").hidden));
    $("#ai-close").addEventListener("click",()=>{toggleAiPanel(false);$("#ai-fab").focus()});
    $("#ai-panel").addEventListener("keydown",event=>{if(event.key==="Escape"){toggleAiPanel(false);$("#ai-fab").focus()}});
    $("#ai-form").addEventListener("submit",event=>{event.preventDefault();const message=$("#ai-input").value.trim();if(!message||aiBusy)return;$("#ai-input").value="";resizeAiInput();sendAi(message)});
    $("#ai-input").addEventListener("input",resizeAiInput);
    $("#ai-input").addEventListener("keydown",event=>{if(event.key==="Enter"&&!event.shiftKey&&!event.isComposing){event.preventDefault();$("#ai-form").requestSubmit()}});
